from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass

logger = BackgroundLogger.Instance()


class Traces(AdminBaseClass):
    """
    Accounts
    """

    def __init__(self):
        super(Traces, self).__init__()

    def start_uplane_trace_stream(self, **kwargs):
        operation = kwargs['operation']
        self.source_ip = kwargs["source_ip"]
        self.dscp = kwargs["dscp"]
        self.destination_ip = kwargs["destination_ip"]
        self.destination_port = kwargs["destination_port"]
        self.timeout = kwargs.pop("timeout",10)
        self.detailed_output = kwargs.pop("detailed_output", False)
        logger.debug("Performing operation  {}...".format(operation.upper().replace("_", " ")))
        try:
            getattr(self, "_{}".format(operation.lower()))(**kwargs)
        except AttributeError:
            raise Exception("Operation {} not supported".format(operation))

    def stop_uplane_trace_stream(self, **kwargs):
        operation = kwargs['operation']
        self.timeout = kwargs.pop("timeout",10)
        self.detailed_output = kwargs.pop("detailed_output", False)
        logger.debug("Performing operation  {}...".format(operation.upper().replace("_", " ")))
        try:
            getattr(self, "_{}".format(operation.lower()))(**kwargs)
        except AttributeError:
            raise Exception("Operation {} not supported".format(operation))

    def _l1_start(self, **kwargs):
        nr_cell_dn = kwargs["nr_cell_dn"]
        traces = kwargs["traces"]
        output_mode = kwargs["output_mode"]
        alias = kwargs.pop("alias", 'default')
        return self.factory.admin.start_uplane_l1_trace(source_ip=self.source_ip, dscp=self.dscp, destination_ip=self.destination_ip,
                                                        destination_port=self.destination_port,nr_cell_dn=nr_cell_dn, traces=traces,
                                                        output_mode=output_mode, timeout=self.timeout,
                                                        connection=alias, detailed_output=self.detailed_output)

    def _l2_start(self, **kwargs):
        nr_cell_dns = kwargs.pop("nr_cell_dns", None)
        trace_type = kwargs.pop("trace_type", 'Component')
        up_sw = kwargs.pop("up_sw",'L2Ps')
        alias = kwargs.pop("alias", 'default')
        return self.factory.admin.start_uplane_l2_trace(source_ip=self.source_ip, dscp=self.dscp, destination_ip=self.destination_ip,
                                                        destination_port=self.destination_port,nr_cell_dns=nr_cell_dns,
                                                        trace_type=trace_type, up_sw=up_sw, timeout=self.timeout,
                                                        connection=alias, detailed_output=self.detailed_output)

    def _l1_stop(self, **kwargs):
        nr_cell_dn = kwargs["nr_cell_dn"]
        alias = kwargs.pop("alias", 'default')
        return self.factory.admin.stop_uplane_l1_trace(nr_cell_dn=nr_cell_dn, timeout=self.timeout,
                                                       connection=alias, detailed_output=self.detailed_output)

    def _l2_stop(self, **kwargs):
        trace_type = kwargs.pop("trace_type", 'Component')
        up_sw = kwargs.pop("up_sw",'L2Ps')
        alias = kwargs.pop("alias", 'default')
        return self.factory.admin.stop_uplane_l2_trace(up_sw=up_sw, trace_type=trace_type, timeout=self.timeout,
                                                       connection=alias, detailed_output=self.detailed_output)